# Matter pages: property (conveyancing, lease extensions). Each becomes /<area>/<matter> plus a partner page
# /partners/<area>-leads/<matter>. Plain, factual copy. No em dashes. No fee figures or promises: the firm quotes.

def m(slug, name, short, intro, help, ready, faqs, firm):
    return {'slug': slug, 'name': name, 'short': short, 'intro': intro, 'help': help, 'ready': ready, 'faqs': faqs, 'firm': firm}


CONVEYANCING = [
    m('buying-a-home', 'Buying a home', 'Conveyancing for your purchase, from offer accepted to keys in hand.',
      ['Once your offer is accepted, a conveyancer does the legal work to make sure you get good title to the property. They check the title deeds, order searches, review the contract and the information the seller provides, and raise questions with the seller’s solicitor about anything that looks wrong.',
       'If you are buying with a mortgage, your conveyancer also acts for your lender, checks the mortgage offer conditions and makes sure the money is in place for completion. After completion, they pay any Stamp Duty Land Tax due and register you as the new owner at HM Land Registry.'],
      ['Checking the title and any restrictions on the property', 'Ordering local authority, water, drainage and environmental searches', 'Reviewing the contract, fixtures and fittings and property information forms',
       'Reporting to you on anything unusual before you commit', 'Exchanging contracts, completing and registering your ownership'],
      ['The address and agreed price', 'The estate agent’s memorandum of sale', 'Your mortgage in principle or offer, if you have one', 'Photo ID and proof of address'],
      [('When should I instruct a conveyancer?', 'As soon as your offer is accepted, or even before. Having a firm lined up means the estate agent can send out the memorandum of sale straight away and the work can start.'),
       ('Do I need a solicitor or a licensed conveyancer?', 'Either can do the work. Solicitors are regulated by the Solicitors Regulation Authority and licensed conveyancers by the Council for Licensed Conveyancers. What matters most is experience with your type of property and being on your lender’s panel.'),
       ('What are disbursements?', 'Costs the firm pays to third parties on your behalf, such as search fees, Land Registry fees and bank transfer fees. A good quote lists them separately from the legal fee.')],
      'Purchase enquiries come with the price, tenure and whether the buyer has a mortgage, so you can quote on the first call.'),
    m('selling-a-home', 'Selling a home', 'Conveyancing for your sale, including redeeming your mortgage.',
      ['When you sell, your conveyancer prepares the contract pack. That includes the title, the property information form, the fittings and contents form and, for leasehold property, the lease and management information. They answer the buyer’s solicitor’s questions and agree a completion date.',
       'On completion they receive the money from the buyer’s solicitor, pay off your mortgage and the estate agent if you ask them to, and send you the balance. Getting the paperwork ready early is the best way to avoid delays later in the chain.'],
      ['Preparing the contract and title documents', 'Helping you complete the property information forms', 'Answering enquiries from the buyer’s solicitor', 'Redeeming your mortgage on completion', 'Paying the estate agent and sending you the proceeds'],
      ['Your title deeds or the name of your mortgage lender', 'Guarantees, building regulation certificates and planning documents', 'Details of any works carried out while you have owned the property', 'Photo ID and proof of address'],
      [('Can I instruct a conveyancer before I find a buyer?', 'Yes, and it often helps. The firm can check your title and prepare the contract pack early, so it is ready to send the day you accept an offer.'),
       ('What if I can’t find a guarantee or certificate?', 'Tell your conveyancer. Missing documents can often be dealt with by indemnity insurance or by getting a copy, and the firm will explain the options.'),
       ('Who pays off my mortgage?', 'Your conveyancer gets a redemption figure from your lender and pays it from the sale money on completion.')],
      'Sale enquiries tell you the rough value, tenure and whether the seller is also buying, which is useful when quoting for both sides.'),
    m('buying-and-selling', 'Buying and selling together', 'One firm handling your sale and your purchase, linked in the chain.',
      ['Most people who move are selling one home and buying another on the same day. Using one firm for both means the two transactions are managed together, so exchange and completion can be lined up and the money from your sale can be used for your purchase.',
       'Your conveyancer keeps track of both sides of the chain and tells you if anything on one transaction might hold up the other.'],
      ['Running your sale and purchase side by side', 'Coordinating exchange and completion dates', 'Using your sale proceeds towards your purchase', 'Dealing with your existing mortgage and any new one', 'Keeping you updated on the chain'],
      ['Details of both properties and the agreed prices', 'Both memoranda of sale', 'Your current and new mortgage details', 'Photo ID and proof of address'],
      [('Is it cheaper to use one firm for both?', 'Many firms offer a combined quote for a sale and purchase. Ask for a breakdown so you can see the fee for each side and the disbursements.'),
       ('What does simultaneous exchange and completion mean?', 'Exchanging contracts and completing on the same day. It is sometimes used to save time, but it leaves little room if something goes wrong, so your conveyancer will talk through whether it suits you.'),
       ('What if my sale falls through?', 'Your conveyancer will tell you where that leaves your purchase and what your options are. Until contracts are exchanged, nobody is legally bound.')],
      'Sale and purchase enquiries are two instructions from one client, and often the most valuable conveyancing leads we generate.'),
    m('remortgaging', 'Remortgaging', 'Legal work for switching your mortgage to a new lender.',
      ['When you remortgage to a new lender, a conveyancer acts for the lender to make sure the new mortgage is properly secured on your property. They check the title, pay off your existing mortgage and register the new charge at HM Land Registry.',
       'Some lenders offer free legal work with a remortgage. If yours doesn’t, or the property or your circumstances are more complicated, you will need to instruct a firm yourself.'],
      ['Checking the title for the new lender', 'Reporting on the mortgage offer conditions', 'Redeeming your existing mortgage', 'Registering the new mortgage', 'Dealing with a transfer of equity at the same time, if needed'],
      ['Your new mortgage offer', 'Details of your existing lender and account', 'Photo ID and proof of address'],
      [('Do I need a solicitor to remortgage?', 'If you are moving to a new lender, the lender will need its legal work done. Some lenders arrange this for free. Otherwise you instruct a conveyancer.'),
       ('How long does a remortgage take?', 'Usually a few weeks from instruction, depending on the lender and any issues with the title. Starting early helps if your current deal is ending.'),
       ('Can I add or remove someone at the same time?', 'Yes. This is a transfer of equity, and many firms handle it alongside the remortgage.')],
      'Remortgage leads are quick, predictable transactions, often with a fixed deadline when the client’s current deal ends.'),
    m('transfer-of-equity', 'Transfer of equity', 'Adding or removing someone from the ownership of a property.',
      ['A transfer of equity changes who owns a property without it being sold. People do this when they marry or move in together, when a relationship ends, or when a parent wants to add a child to the title.',
       'If there is a mortgage, the lender has to agree. The conveyancer prepares the transfer deed, deals with the lender and registers the change at HM Land Registry. Stamp Duty Land Tax can apply in some cases, and the firm will tell you if it does.'],
      ['Preparing the transfer deed', 'Getting the lender’s consent', 'Checking whether Stamp Duty Land Tax is payable', 'Registering the change of ownership', 'Advising each owner, or referring one to another firm where needed'],
      ['The property address and title number if you have it', 'Details of everyone being added or removed', 'Mortgage lender details', 'Any separation or court order that applies'],
      [('Do I need the lender’s permission?', 'Yes, if the property is mortgaged. The lender will want to check the person being added can afford the mortgage, or that the remaining owner can after someone is removed.'),
       ('Does a transfer of equity cost Stamp Duty?', 'It can, depending on whether money or debt changes hands. Your conveyancer will check and explain.'),
       ('Can the same firm act for everyone?', 'Sometimes. Where owners’ interests differ, for example after a separation, the firm may recommend that one person takes separate advice.')],
      'Transfer of equity enquiries often follow a marriage, separation or remortgage, and can lead to related family or property work.'),
    m('first-time-buyers', 'First time buyers', 'Conveyancing explained step by step for your first purchase.',
      ['Buying your first home involves a lot of new language, such as searches, enquiries, exchange and completion. A good conveyancer explains each step in plain English and tells you what they need from you and when.',
       'First time buyers may qualify for relief on Stamp Duty Land Tax, and some use schemes such as shared ownership or a Lifetime ISA. Your conveyancer checks how these apply and makes sure the paperwork is right.'],
      ['Explaining the process from offer to completion', 'Checking how first time buyer relief applies', 'Dealing with shared ownership or Lifetime ISA paperwork', 'Reporting to you on the property before you commit', 'Completing and registering your ownership'],
      ['The address and agreed price', 'Your mortgage in principle or offer', 'Details of any scheme you are using', 'Photo ID and proof of address'],
      [('What does a conveyancer do for a first time buyer?', 'The same legal work as for any purchase, but with more explanation along the way. The firm checks the property, reports to you and handles the money and registration.'),
       ('Will I pay Stamp Duty?', 'It depends on the price and whether you qualify for first time buyer relief. Your conveyancer will confirm what is due.'),
       ('How long will it take?', 'Many purchases take a few months from offer to completion. The length of the chain, searches and mortgage offer all make a difference.')],
      'First time buyers are often the most responsive clients, with no chain behind them and keen to get started.'),
    m('buy-to-let', 'Buy to let purchases', 'Conveyancing for landlords buying in their own name or through a company.',
      ['Buying a property to rent out involves the usual purchase work plus a few extra checks. Buy to let mortgages have their own conditions, there may be existing tenants, and buying through a limited company changes the paperwork.',
       'Your conveyancer will also check for anything that affects letting, such as restrictions in a lease, and explain the Stamp Duty Land Tax position, which is often higher for additional properties.'],
      ['Purchases in a personal name or a limited company', 'Checking lease terms that affect letting', 'Buying with tenants in place', 'Reviewing buy to let mortgage conditions', 'Explaining the Stamp Duty position for additional properties'],
      ['The address and agreed price', 'Whether you are buying personally or through a company', 'Your buy to let mortgage offer, if you have one', 'Details of any existing tenancy'],
      [('Can I buy a rental property through a company?', 'Yes. The conveyancer will need company details and the lender will usually want personal guarantees from the directors.'),
       ('Does buy to let cost more in Stamp Duty?', 'Additional properties usually attract a higher rate. Your conveyancer will confirm what applies to you.'),
       ('Can I buy a flat with a tenant already in it?', 'Yes. The firm will check the tenancy agreement, the deposit protection and what happens on completion.')],
      'Landlord enquiries often lead to repeat instructions as investors grow their portfolio.'),
    m('new-build-purchases', 'New build purchases', 'Buying a newly built home from a developer.',
      ['New build purchases work differently. Developers set tight deadlines to exchange, the property may not be finished when you sign, and completion happens on notice once it is ready.',
       'Your conveyancer checks the developer’s contract, the planning and building warranty, any estate management charges and the specification, so you know exactly what you are buying.'],
      ['Reviewing the developer’s contract and deadlines', 'Checking the warranty, planning and road adoption', 'Explaining estate charges and management companies', 'Dealing with help to buy or incentive schemes', 'Completing on notice when the home is ready'],
      ['The reservation form and developer’s sales pack', 'Your mortgage offer or in principle', 'Details of any incentive or scheme', 'Photo ID and proof of address'],
      [('Why do developers set short deadlines?', 'They want to secure the sale quickly. Your conveyancer will tell you if the deadline is realistic and what happens if it is missed.'),
       ('Should I use the developer’s recommended solicitor?', 'You are free to choose your own. An independent firm acts only for you.'),
       ('What if the home isn’t finished on time?', 'Your contract will say what happens. The conveyancer will explain your position before you exchange.')],
      'New build buyers are working to developer deadlines, so they want a firm that can start straight away.'),
    m('buying-a-leasehold-flat', 'Buying a leasehold flat', 'The extra checks needed when you buy a flat on a lease.',
      ['When you buy a leasehold flat, you are buying the right to live there for the remaining years of the lease. Your conveyancer checks the lease carefully, including how long is left, the ground rent, the service charge, and what you can and can’t do.',
       'They also get information from the freeholder or managing agent about service charges, planned works and any disputes. A short lease can affect your mortgage and the value of the flat, so the firm will flag it early.'],
      ['Reviewing the lease and how many years remain', 'Checking ground rent and service charges', 'Getting the management pack from the managing agent', 'Flagging a short lease and explaining your options', 'Dealing with the freeholder on completion'],
      ['The address and agreed price', 'Anything the agent has said about the lease length', 'Your mortgage in principle or offer', 'Photo ID and proof of address'],
      [('How many years should be left on a lease?', 'Many lenders want a minimum term remaining when the mortgage ends. Leases with fewer than 80 years left can be more expensive to extend. Your conveyancer will explain what it means for you.'),
       ('What is a management pack?', 'Information from the freeholder or managing agent about service charges, insurance, planned works and any disputes. There is usually a fee for it.'),
       ('Can the seller extend the lease before I buy?', 'Sometimes. The seller can start a statutory lease extension and pass the benefit to you, which your conveyancer can arrange.')],
      'Leasehold purchases are more complex, which means higher fees and often a related lease extension instruction.'),
]

LEASE = [
    m('statutory-lease-extension', 'Statutory lease extensions', 'Extending your lease using your legal right as a qualifying leaseholder.',
      ['Many flat owners have a legal right to extend their lease, using a formal process with set steps and deadlines. It starts with a notice to the freeholder, which the freeholder must respond to, and any disagreement about the premium can go to a tribunal.',
       'The law on leasehold is changing, so the right process and the way the premium is worked out depend on when you start. A solicitor will check what applies to you, work with a surveyor on the valuation and serve the notices correctly.'],
      ['Checking whether you qualify', 'Arranging a valuation with a specialist surveyor', 'Preparing and serving the notice on the freeholder', 'Negotiating the premium and terms', 'Completing the new lease and registering it'],
      ['Your lease, or the title number', 'Roughly how many years are left', 'Freeholder and managing agent details', 'Whether you are selling or remortgaging soon'],
      [('Why extend my lease?', 'As a lease gets shorter, the flat can become harder to sell or mortgage and more expensive to extend. Extending protects the value of your home.'),
       ('How long does a statutory extension take?', 'Often several months, longer if the premium has to go to a tribunal. Starting before you plan to sell gives you time.'),
       ('Do I pay the freeholder’s costs?', 'Usually you pay certain reasonable costs of the freeholder as well as your own. Your solicitor will explain the current rules.')],
      'Statutory extensions are formal, deadline-driven instructions that need a specialist, and they are often linked to a sale.'),
    m('informal-lease-extension', 'Informal lease extensions', 'Agreeing a lease extension directly with your freeholder.',
      ['An informal extension is agreed by negotiation rather than through the statutory process. It can be quicker, and some freeholders offer it, but the terms are whatever you agree, which can include a higher ground rent or other changes.',
       'A solicitor will review the terms offered, compare them with what you might get through the statutory route and make sure the new lease protects you.'],
      ['Reviewing the freeholder’s offer', 'Comparing it with the statutory route', 'Negotiating terms such as ground rent', 'Preparing and completing the new lease', 'Registering it at HM Land Registry'],
      ['Your lease and any offer from the freeholder', 'Roughly how many years are left', 'Freeholder details', 'Any deadline, such as a sale'],
      [('Is an informal extension a good idea?', 'It can be, if the terms are fair. Your solicitor will tell you what to look out for, such as ground rent increases.'),
       ('Can I switch to the statutory route?', 'Usually, if you qualify. Your solicitor will explain the timing.'),
       ('Will my lender need to know?', 'Yes. Your lender usually has to consent to the new lease.')],
      'Informal extension enquiries often need advice on whether to accept an offer, which is a quick, valuable instruction.'),
    m('collective-enfranchisement', 'Collective enfranchisement', 'Flat owners buying the freehold of their building together.',
      ['Collective enfranchisement is the right of qualifying flat owners in a building to buy the freehold together. Once they own it, they can grant themselves longer leases and manage the building themselves.',
       'It needs enough flat owners to take part, usually through a company set up for the purpose, and a careful process with notices and deadlines. A solicitor coordinates the participants, the valuation and the negotiation.'],
      ['Checking whether the building qualifies', 'Organising participating leaseholders and a nominee company', 'Coordinating valuations', 'Serving notices and negotiating with the freeholder', 'Completing the purchase and granting new leases'],
      ['The building address and number of flats', 'How many owners are interested', 'Freeholder details', 'Any leases you have to hand'],
      [('How many flat owners need to take part?', 'There are minimum participation rules. Your solicitor will check them for your building.'),
       ('What happens after we buy the freehold?', 'The participating owners control the freehold, can extend their own leases and decide how the building is managed.'),
       ('Do all owners have to pay the same?', 'Not always. Contributions are usually agreed between participants, often based on each flat’s value.')],
      'Enfranchisement involves several clients in one building, a significant instruction for a leasehold team.'),
    m('short-lease', 'Flats with a short lease', 'What to do when your lease is running down.',
      ['If your lease has fewer than 80 years left, it can be harder to sell or remortgage, and extending it may cost more. Many people only find out when a buyer’s surveyor or a lender raises it.',
       'A solicitor will look at your lease, explain your options for extending and the likely timescale, and work with a surveyor so you know the cost before you commit.'],
      ['Checking how long is left and what it means', 'Explaining statutory and informal options', 'Arranging a valuation', 'Starting an extension before a sale', 'Assigning the benefit of a notice to a buyer'],
      ['Your lease or title number', 'Roughly how many years are left', 'Whether you are selling or remortgaging', 'Freeholder details'],
      [('Is 80 years important?', 'It has historically affected the cost of extending. The rules are changing, so your solicitor will explain what applies now.'),
       ('Can I sell a flat with a short lease?', 'Yes, but some buyers can’t get a mortgage on it. Starting an extension before you sell can help.'),
       ('Should I extend now or wait?', 'It depends on your plans and the current rules. A solicitor can explain the pros and cons for your situation.')],
      'Short lease enquiries are motivated, because the client usually has a sale or remortgage depending on it.'),
    m('lease-variations', 'Lease variations', 'Changing the terms of a lease that is defective or out of date.',
      ['Some leases have mistakes or terms that no longer work, such as the wrong plan, unclear repair obligations, or a ground rent that doubles regularly. These can put off buyers and lenders.',
       'A lease can be changed by agreement with the freeholder, and in some cases through a tribunal. A solicitor will identify the problem, propose the change and prepare the deed of variation.'],
      ['Identifying defects in the lease', 'Negotiating changes with the freeholder', 'Dealing with onerous ground rent terms', 'Preparing a deed of variation', 'Registering the change'],
      ['Your lease', 'What the problem is, if you know', 'Freeholder details', 'Any letters from a buyer or lender'],
      [('What is a deed of variation?', 'A legal document that changes the terms of an existing lease, signed by the leaseholder and freeholder.'),
       ('Can my freeholder refuse?', 'They can, but some defects can be put right through a tribunal. Your solicitor will explain.'),
       ('Can this be done with a lease extension?', 'Often, yes. Changes can be agreed as part of a new lease.')],
      'Variation enquiries usually come from a stalled sale or remortgage, so the client needs a firm that acts quickly.'),
    m('selling-a-leasehold-flat', 'Selling a leasehold flat', 'Getting a leasehold sale ready, including lease issues.',
      ['Selling a leasehold flat means providing the buyer with the lease, a management pack and answers about service charges and works. If the lease is short or has unusual terms, buyers and lenders will ask about it.',
       'A solicitor can prepare the paperwork early and, if needed, start a lease extension so the sale isn’t held up.'],
      ['Preparing the leasehold sale pack', 'Getting the management information', 'Dealing with a short lease before or during the sale', 'Answering buyer enquiries', 'Paying the freeholder and agent on completion'],
      ['Your lease and service charge details', 'Freeholder and managing agent details', 'Roughly how many years are left', 'Estate agent details'],
      [('Why do leasehold sales take longer?', 'The buyer needs information from the freeholder or managing agent, which can take time to arrive.'),
       ('Should I extend before selling?', 'It can make the flat easier to sell. A solicitor can start the process and pass the benefit to your buyer.'),
       ('Who pays for the management pack?', 'Usually the seller. Your solicitor will order it.')],
      'Leasehold sellers often need two pieces of work, the sale and a lease extension.'),
]
